import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M1 0h4a1 1 0 0 1 0 2H2v3a1 1 0 0 1-2 0V1a1 1 0 0 1 1-1M0 15v-4a1 1 0 1 1 2 0v3h3a1 1 0 1 1 0 2H1a1 1 0 0 1-1-1m16 0a1 1 0 0 1-1 1h-4a1 1 0 1 1 0-2h3v-3a1 1 0 1 1 2 0zm0-14v4a1 1 0 1 1-2 0V2h-3a1 1 0 1 1 0-2h4a1 1 0 0 1 1 1M5 4h6a1 1 0 0 1 1 1v6a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V5a1 1 0 0 1 1-1m1 2v4h4V6z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M1 0h5a1 1 0 0 1 0 2H2v4a1 1 0 0 1-2 0V1a1 1 0 0 1 1-1M0 19v-5a1 1 0 1 1 2 0v4h4a1 1 0 0 1 0 2H1a1 1 0 0 1-1-1m19 1h-5a1 1 0 0 1 0-2h4v-4a1 1 0 0 1 2 0v5a1 1 0 0 1-1 1m1-19v5a1 1 0 0 1-2 0V2h-4a1 1 0 1 1 0-2h5a1 1 0 0 1 1 1M5 6a1 1 0 0 1 1-1h8a1 1 0 0 1 1 1v8a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1zm2 7h6V7H7z"] as readonly string[];

export const DetectionIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="detection" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
DetectionIcon.displayName = `Blueprint6.Icon.DetectionIcon`;

/**
 * @deprecated Use {@link DetectionIcon} instead.
 */
export const Detection: typeof DetectionIcon = DetectionIcon;

export default DetectionIcon;
